import React, { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import { verifyCertificate, verifyCertificateById, getQrCode } from '../services/api';
import { toast } from 'react-toastify';
import LoadingSpinner from '../components/LoadingSpinner';
import {
  HiOutlineShieldCheck,
  HiOutlineCheckCircle,
  HiOutlineXCircle,
  HiOutlineSearch,
  HiOutlineFingerPrint,
  HiOutlineIdentification,
  HiOutlineClock,
  HiOutlineAcademicCap,
  HiOutlineOfficeBuilding,
  HiOutlineUser,
  HiOutlineQrcode,
} from 'react-icons/hi';

const VerifyPage = () => {
  const { certificateId: urlCertId } = useParams();
  const [activeTab, setActiveTab] = useState('id');
  const [inputValue, setInputValue] = useState('');
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);
  const [verified, setVerified] = useState(false);

  useEffect(() => {
    if (urlCertId) {
      setInputValue(urlCertId);
      setActiveTab('id');
      handleVerify(urlCertId, 'id');
    }
  }, [urlCertId]);

  const handleVerify = async (value, type) => {
    const searchValue = value || inputValue;
    const searchType = type || activeTab;

    if (!searchValue.trim()) {
      toast.error('Please enter a certificate ID or hash');
      return;
    }

    setLoading(true);
    setResult(null);
    setVerified(false);

    try {
      let response;

      if (searchType === 'id') {
        try {
          response = await verifyCertificateById(searchValue.trim());
        } catch {
          response = await verifyCertificate({ certificateId: searchValue.trim() });
        }
      } else {
        response = await verifyCertificate({ certificateHash: searchValue.trim() });
      }

      setResult(response.data);
      setVerified(true);
    } catch (error) {
      if (error.response?.status === 404) {
        setResult({ valid: false, message: 'Certificate not found' });
        setVerified(true);
      } else {
        const message =
          error.response?.data?.message ||
          error.response?.data?.error ||
          'Verification failed. Please try again.';
        toast.error(typeof message === 'string' ? message : 'Verification failed');
        setResult({ valid: false, message: 'Verification failed' });
        setVerified(true);
      }
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    handleVerify();
  };

  const resetVerification = () => {
    setResult(null);
    setVerified(false);
    setInputValue('');
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-primary-50 via-white to-blue-50">
      <div className="max-w-3xl mx-auto px-4 sm:px-6 lg:px-8 py-12">
        {/* Header */}
        <div className="text-center mb-10">
          <div className="inline-flex items-center justify-center w-16 h-16 rounded-2xl bg-gradient-to-br from-primary-500 to-primary-700 text-white mb-4 shadow-lg shadow-primary-200">
            <HiOutlineShieldCheck className="h-8 w-8" />
          </div>
          <h1 className="text-3xl sm:text-4xl font-bold text-gray-900">Verify Certificate</h1>
          <p className="mt-2 text-gray-500 max-w-xl mx-auto">
            Enter a certificate ID or hash to instantly verify its authenticity on the blockchain.
          </p>
        </div>

        {/* Verification Form */}
        <div className="card mb-8">
          {/* Tabs */}
          <div className="flex border-b border-gray-200 mb-6">
            <button
              className={`flex items-center px-4 py-3 text-sm font-medium border-b-2 transition-colors ${
                activeTab === 'id'
                  ? 'border-primary-600 text-primary-600'
                  : 'border-transparent text-gray-500 hover:text-gray-700'
              }`}
              onClick={() => {
                setActiveTab('id');
                resetVerification();
              }}
            >
              <HiOutlineIdentification className="h-4 w-4 mr-2" />
              Verify by Certificate ID
            </button>
            <button
              className={`flex items-center px-4 py-3 text-sm font-medium border-b-2 transition-colors ${
                activeTab === 'hash'
                  ? 'border-primary-600 text-primary-600'
                  : 'border-transparent text-gray-500 hover:text-gray-700'
              }`}
              onClick={() => {
                setActiveTab('hash');
                resetVerification();
              }}
            >
              <HiOutlineFingerPrint className="h-4 w-4 mr-2" />
              Verify by Hash
            </button>
          </div>

          <form onSubmit={handleSubmit}>
            <div className="flex flex-col sm:flex-row gap-3">
              <div className="flex-1 relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <HiOutlineSearch className="h-5 w-5 text-gray-400" />
                </div>
                <input
                  type="text"
                  value={inputValue}
                  onChange={(e) => setInputValue(e.target.value)}
                  className="input-field pl-10 !py-3"
                  placeholder={
                    activeTab === 'id'
                      ? 'Enter certificate ID...'
                      : 'Enter SHA-256 hash...'
                  }
                />
              </div>
              <button
                type="submit"
                disabled={loading}
                className="btn-primary !py-3 whitespace-nowrap disabled:opacity-50"
              >
                {loading ? (
                  <div className="flex items-center">
                    <div className="h-4 w-4 animate-spin rounded-full border-2 border-white border-t-transparent mr-2" />
                    Verifying...
                  </div>
                ) : (
                  <>
                    <HiOutlineShieldCheck className="h-5 w-5 mr-2" />
                    Verify
                  </>
                )}
              </button>
            </div>
          </form>
        </div>

        {/* Loading */}
        {loading && <LoadingSpinner text="Verifying certificate on blockchain..." />}

        {/* Result */}
        {verified && result && !loading && (
          <div className="card">
            {result.valid || result.certificateDetails ? (
              /* Valid Certificate */
              <div>
                <div className="text-center mb-6">
                  <div className="inline-flex items-center justify-center w-20 h-20 rounded-full bg-green-100 mb-4">
                    <HiOutlineCheckCircle className="h-12 w-12 text-green-600" />
                  </div>
                  <h2 className="text-2xl font-bold text-green-700">Certificate is Valid</h2>
                  <p className="text-gray-500 mt-1">
                    {result.message || 'This certificate has been verified on the blockchain.'}
                  </p>
                </div>

                {result.certificateDetails && (
                  <div className="bg-green-50 rounded-xl p-6 mb-6">
                    <h3 className="text-sm font-semibold text-green-800 uppercase tracking-wider mb-4">
                      Certificate Details
                    </h3>
                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                      {result.certificateDetails.studentName && (
                        <div className="flex items-start space-x-2">
                          <HiOutlineUser className="h-4 w-4 text-green-600 mt-0.5" />
                          <div>
                            <p className="text-xs text-green-600 font-medium">Student</p>
                            <p className="text-sm text-gray-900">
                              {result.certificateDetails.studentName}
                            </p>
                          </div>
                        </div>
                      )}

                      {result.certificateDetails.courseName && (
                        <div className="flex items-start space-x-2">
                          <HiOutlineAcademicCap className="h-4 w-4 text-green-600 mt-0.5" />
                          <div>
                            <p className="text-xs text-green-600 font-medium">Course</p>
                            <p className="text-sm text-gray-900">
                              {result.certificateDetails.courseName}
                            </p>
                          </div>
                        </div>
                      )}

                      {result.certificateDetails.institutionName && (
                        <div className="flex items-start space-x-2">
                          <HiOutlineOfficeBuilding className="h-4 w-4 text-green-600 mt-0.5" />
                          <div>
                            <p className="text-xs text-green-600 font-medium">Institution</p>
                            <p className="text-sm text-gray-900">
                              {result.certificateDetails.institutionName}
                            </p>
                          </div>
                        </div>
                      )}

                      {result.certificateDetails.grade && (
                        <div className="flex items-start space-x-2">
                          <HiOutlineAcademicCap className="h-4 w-4 text-green-600 mt-0.5" />
                          <div>
                            <p className="text-xs text-green-600 font-medium">Grade</p>
                            <p className="text-sm text-gray-900">
                              {result.certificateDetails.grade}
                            </p>
                          </div>
                        </div>
                      )}

                      {result.certificateDetails.issueDate && (
                        <div className="flex items-start space-x-2">
                          <HiOutlineClock className="h-4 w-4 text-green-600 mt-0.5" />
                          <div>
                            <p className="text-xs text-green-600 font-medium">Issue Date</p>
                            <p className="text-sm text-gray-900">
                              {new Date(result.certificateDetails.issueDate).toLocaleDateString()}
                            </p>
                          </div>
                        </div>
                      )}

                      {result.certificateDetails.status && (
                        <div className="flex items-start space-x-2">
                          <HiOutlineShieldCheck className="h-4 w-4 text-green-600 mt-0.5" />
                          <div>
                            <p className="text-xs text-green-600 font-medium">Status</p>
                            <p className="text-sm text-gray-900">
                              {result.certificateDetails.status}
                            </p>
                          </div>
                        </div>
                      )}
                    </div>
                  </div>
                )}

                {/* Verification Metadata */}
                <div className="bg-gray-50 rounded-xl p-4 space-y-2 text-sm">
                  {result.verificationTimestamp && (
                    <div className="flex justify-between">
                      <span className="text-gray-500">Verified At</span>
                      <span className="text-gray-900 font-medium">
                        {new Date(result.verificationTimestamp).toLocaleString()}
                      </span>
                    </div>
                  )}
                  {result.transactionId && (
                    <div className="flex justify-between">
                      <span className="text-gray-500">Transaction ID</span>
                      <span className="text-gray-900 font-mono text-xs">
                        {result.transactionId.substring(0, 20)}...
                      </span>
                    </div>
                  )}
                </div>

                {/* QR Code */}
                {result.certificateDetails?.certificateId && (
                  <div className="text-center mt-6">
                    <div className="flex items-center justify-center mb-2">
                      <HiOutlineQrcode className="h-4 w-4 text-gray-500 mr-1" />
                      <span className="text-sm text-gray-500">Scan QR Code</span>
                    </div>
                    <div className="inline-block p-3 bg-white rounded-xl border border-gray-200">
                      <img
                        src={getQrCode(result.certificateDetails.certificateId)}
                        alt="QR Code"
                        className="w-32 h-32"
                        onError={(e) => {
                          e.target.style.display = 'none';
                        }}
                      />
                    </div>
                  </div>
                )}
              </div>
            ) : (
              /* Invalid Certificate */
              <div className="text-center py-8">
                <div className="inline-flex items-center justify-center w-20 h-20 rounded-full bg-red-100 mb-4">
                  <HiOutlineXCircle className="h-12 w-12 text-red-600" />
                </div>
                <h2 className="text-2xl font-bold text-red-700">Certificate Not Found</h2>
                <p className="text-gray-500 mt-2 max-w-md mx-auto">
                  {result.message ||
                    'The certificate could not be verified. Please check the ID or hash and try again.'}
                </p>
                <button
                  onClick={resetVerification}
                  className="btn-primary mt-6"
                >
                  Try Again
                </button>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default VerifyPage;
